#include <stdatomic.h>
#include <stdbool.h>

// Assuming base::subtle::Atomic32 is equivalent to atomic_int in C11
bool FinalizeAsyncPixelTransfer(atomic_int* submit_count) {
    // Retrieve shared memory buffer
    void* shared_buffer = GetSharedMemoryBuffer();
    if (!shared_buffer) {
        return false;
    }

    // Set up memory parameters for the pixel transfer
    MemoryParameters params;
    if (!SetupMemoryParameters(&params)) {
        return false;
    }

    // Create observer for completion notification
    TransferCompletionObserver* observer = CreateTransferObserver();
    if (!observer) {
        return false;
    }

    // Request AsyncPixelTransferManager to notify when done
    AsyncPixelTransferManager* manager = GetAsyncPixelTransferManager();
    if (!manager || !manager->RequestNotification(observer)) {
        return false;
    }

    // Add the operation to the pending transfer queue
    return AddToPendingTransferQueue(params, shared_buffer, observer);
}

bool finalize_async_pixel_transfer(base::subtle::Atomic32 submit_count) {
    SharedMemory* memory_buffer = get_shared_memory_buffer();
    if (!memory_buffer || !memory_buffer->is_valid()) {
        return false;
    }

    MemoryParameters memory_params;
    memory_params.buffer_address = memory_buffer->get_address();
    memory_params.size = memory_buffer->get_size();

    AsyncPixelTransferObserver* observer = create_observer();
    if (!observer) {
        return false;
    }

    if (!AsyncPixelTransferManager::NotifyWhenDone(observer)) {
        return false;
    }

    return pending_transfer_queue_add(memory_params, submit_count, observer);
}

