bool is_shared_memory_valid();
void setup_memory_parameters();
void create_observer();
void request_notification();
bool add_to_pending_transfer_queue();

bool finalize_async_pixel_transfer(base::subtle::Atomic32 submit_count) {
    if (!is_shared_memory_valid()) {
        return false;
    }

    setup_memory_parameters();
    create_observer();

    request_notification();

    return add_to_pending_transfer_queue();
